import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOutfit = makeLoadFont('Outfit');

// Cera Pro is a commercial font; Outfit is a highly comparable geometric sans available via Google Fonts.
const { fontFamily: outfitFamily } = loadOutfit();



export type TextRevealProps = Record<string, any>;

const TextReveal: React.FC<TextRevealProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 5,
  text = "If you're thinking of building a business today",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling
  const minDimension = Math.min(width, height);
  const fontSize = minDimension * 0.09;
  
  // Split text into words for staggered animation
  const words = text.split(" ");

  // Global subtle scale for the entire text block to keep the scene alive
  const globalScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0.95, 1.05],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: outfitFamily }}>
      <div
        style={{
          flex: 1,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          padding: `${height * 0.1}px ${width * 0.15}px`,
        }}
      >
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            columnGap: `${fontSize * 0.25}px`,
            rowGap: `${fontSize * 0.1}px`,
            width: "100%",
            maxWidth: width * 0.7, // Keeps text constrained within safe zones
            transform: `scale(${globalScale})`,
            transition: "none",
          }}
        >
          {words.map((word, i) => {
            // Stagger each word by 3 frames
            const wordDelay = i * 3;
            
            // Calculate spring for smooth translation and rotation
            const wordSpring = spring({
              frame: frame - wordDelay,
              fps,
              config: {
                damping: 14,
                stiffness: 120,
                mass: 0.8,
              },
            });

            const translateY = interpolate(wordSpring, [0, 1], [120, 0]);
            const rotateX = interpolate(wordSpring, [0, 1], [60, 0]);
            const opacity = interpolate(wordSpring, [0, 0.5, 1], [0, 0.5, 1], {
              extrapolateRight: "clamp",
            });

            return (
              <div
                key={`${word}-${i}`}
                style={{
                  overflow: "hidden", // Masks the incoming word
                  display: "inline-flex",
                  paddingBottom: `${fontSize * 0.1}px`, // Prevents clipping on descenders
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontSize: `${fontSize}px`,
                    fontWeight: 600,
                    color: textColor,
                    lineHeight: 1.1,
                    letterSpacing: "-0.02em",
                    opacity,
                    transform: `translateY(${translateY}%) rotateX(${rotateX}deg)`,
                    transformOrigin: "bottom center",
                    display: "inline-block",
                    transition: "none",
                  }}
                >
                  {word}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TextReveal;